/* ===== 00-core.js ===== */
/* Ngôi Sao A+ — core helpers (random, formatting, answer checking) */
(function (HV) {
  'use strict';
  const U = HV.U = {};
  HV.BRAND = 'Ngôi Sao A+';           // tên ứng dụng (dưới biểu tượng và trên cửa hàng)
  HV.VERSION = '1.1';

  // ---------- random ----------
  U.int = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
  U.pick = arr => arr[Math.floor(Math.random() * arr.length)];
  U.chance = p => Math.random() < p;
  U.shuffle = arr => {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  };
  U.sample = (arr, k) => U.shuffle(arr).slice(0, k);
  U.range = (a, b) => { const r = []; for (let i = a; i <= b; i++) r.push(i); return r; };
  U.intNot = (a, b, bad) => { // random int in [a,b] not in bad list
    const pool = U.range(a, b).filter(x => bad.indexOf(x) < 0);
    return pool.length ? U.pick(pool) : U.int(a, b);
  };
  U.uid = (p) => (p || '') + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);

  // ---------- number theory ----------
  U.gcd = (a, b) => { a = Math.abs(a); b = Math.abs(b); while (b) { const t = a % b; a = b; b = t; } return a; };
  U.lcm = (a, b) => a / U.gcd(a, b) * b;
  U.isPrime = n => { if (n < 2) return false; for (let i = 2; i * i <= n; i++) if (n % i === 0) return false; return true; };
  U.factorize = n => { const f = []; let d = 2; while (n > 1) { while (n % d === 0) { f.push(d); n /= d; } d++; if (d * d > n && n > 1) { f.push(n); break; } } return f; };
  U.reduce = (n, d) => { if (d < 0) { n = -n; d = -d; } const g = U.gcd(n, d) || 1; return [n / g, d / g]; };
  U.round = (x, dp) => { const k = Math.pow(10, dp); return Math.round((x + (x >= 0 ? 1e-12 : -1e-12)) * k) / k; };

  // ---------- formatting (Vietnamese conventions) ----------
  U.esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  U.trimDec = x => {
    let s = (Math.round(x * 1e9) / 1e9).toFixed(9);
    if (s.indexOf('.') >= 0) s = s.replace(/0+$/, '').replace(/\.$/, '');
    if (s === '-0') s = '0';
    return s;
  };
  // 12345.5 -> "12 345,5" (narrow no-break space grouping for >= 5 digits), negatives with "−"
  U.fmt = n => {
    if (typeof n !== 'number' || !isFinite(n)) return String(n);
    const neg = n < 0;
    const s = U.trimDec(Math.abs(n));
    let parts = s.split('.');
    let ip = parts[0];
    if (ip.length > 4) ip = ip.replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
    return (neg && s !== '0' ? '−' : '') + ip + (parts[1] ? ',' + parts[1] : '');
  };
  U.fmtP = n => (n < 0 ? '(' + U.fmt(n) + ')' : U.fmt(n)); // parenthesise negatives
  U.money = n => U.fmt(n) + ' đồng';
  // fraction html
  U.fr = (n, d) => '<span class="fr"><span class="fr-n">' + n + '</span><span class="fr-d">' + d + '</span></span>';
  // signed fraction from integers (not reduced automatically)
  U.F = (n, d) => {
    if (d < 0) { n = -n; d = -d; }
    if (d === 1) return U.fmt(n);
    return (n < 0 ? '−' : '') + U.fr(U.fmt(Math.abs(n)), U.fmt(d));
  };
  U.FP = (n, d) => (n < 0 || (d < 0 && n > 0) ? '(' + U.F(n, d) + ')' : U.F(n, d));
  U.FR = (n, d) => { const r = U.reduce(n, d); return U.F(r[0], r[1]); }; // reduced
  U.rt = x => '<span class="rt">√<span class="ov">' + x + '</span></span>';
  U.cbrt = x => '<span class="rt">∛<span class="ov">' + x + '</span></span>';
  U.v = s => '<i class="var">' + s + '</i>';
  U.sup = n => '<sup>' + n + '</sup>';
  U.box = (txt) => '<span class="box">' + (txt == null ? '?' : txt) + '</span>';
  U.steps = lines => '<div class="ex-steps">' + lines.filter(Boolean).map(l => '<p>' + l + '</p>').join('') + '</div>';
  U.ans = s => '<b class="hl">' + s + '</b>';

  // polynomial in one variable from coefficient list (highest degree first)
  U.poly = (coeffs, v) => {
    v = v || 'x';
    const deg = coeffs.length - 1;
    let out = '';
    coeffs.forEach((c, i) => {
      if (!c) return;
      const p = deg - i;
      const abs = Math.abs(c);
      let term;
      if (p === 0) term = U.fmt(abs);
      else term = (abs === 1 ? '' : U.fmt(abs)) + U.v(v) + (p > 1 ? U.sup(p) : '');
      if (!out) out = (c < 0 ? '−' : '') + term;
      else out += (c < 0 ? ' − ' : ' + ') + term;
    });
    return out || '0';
  };
  // linear factor (ax + b) html
  U.lin = (a, b, v) => U.poly([a, b], v);

  // strip html -> plain text (for AI prompts / speech)
  U.plain = html => String(html)
    .replace(/<span class="fr"><span class="fr-n">(.*?)<\/span><span class="fr-d">(.*?)<\/span><\/span>/g, '($1)/($2)')
    .replace(/<sup>(.*?)<\/sup>/g, '^$1')
    .replace(/<br\s*\/?>/g, '\n').replace(/<\/p>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

  // ---------- multiple choice builders ----------
  const key = v => (typeof v === 'number' ? 'n' + Math.round(v * 1e7) : 's' + String(v));
  // numeric options: correct number + candidate distractors (numbers). opts: {fmt, n, min, int, step}
  U.mcNum = (correct, cands, o) => {
    o = o || {};
    const f = o.fmt || U.fmt;
    const n = o.n || 4;
    const seen = new Set([key(correct)]);
    const seenTxt = new Set([f(correct)]);
    const list = [correct];
    const ok = c => typeof c === 'number' && isFinite(c) && !(o.min != null && c < o.min) && !(o.max != null && c > o.max) && !(o.int && !Number.isInteger(c));
    const tryAdd = c => {
      if (list.length >= n || !ok(c)) return;
      const k = key(c), t = f(c);
      if (seen.has(k) || seenTxt.has(t)) return;
      seen.add(k); seenTxt.add(t); list.push(c);
    };
    (cands || []).forEach(tryAdd);
    let guard = 0;
    const step = o.step || 1;
    while (list.length < n && guard++ < 400) {
      const spread = Math.max(2, Math.round(Math.abs(correct) * 0.15 / step));
      tryAdd(correct + U.int(1, spread + Math.floor(guard / 40)) * step * (U.chance(0.5) ? 1 : -1));
    }
    const sh = U.shuffle(list);
    return { t: 'mc', opts: sh.map(f), a: sh.indexOf(correct), _v: correct };
  };
  // string options: first = correct
  U.mcStr = (correct, wrongs, n) => {
    n = n || 4;
    const list = [correct];
    (wrongs || []).forEach(w => { if (list.length < n && w != null && list.indexOf(w) < 0) list.push(w); });
    const sh = U.shuffle(list);
    return { t: 'mc', opts: sh, a: sh.indexOf(correct) };
  };
  // keep fixed order (e.g. >,<,= or Đúng/Sai)
  U.mcFixed = (opts, correctIdx) => ({ t: 'mc', opts: opts.slice(), a: correctIdx, fixed: true });

  // numeric input answer
  U.num = (v, o) => Object.assign({ t: 'num', a: { kind: Number.isInteger(v) ? 'int' : 'dec', v: v }, _v: v }, o || {});
  U.fracAns = (n, d, o) => { const r = U.reduce(n, d); return Object.assign({ t: 'num', a: { kind: 'frac', v: r, simplest: true }, _v: r[0] / r[1] }, o || {}); };

  // ---------- answer checking ----------
  U.normNum = s => String(s == null ? '' : s).trim()
    .replace(/[\s  ]/g, '').replace(/[−–—]/g, '-').replace(/\./g, ',');
  U.parseNum = s => {
    s = U.normNum(s);
    if (!s) return null;
    let m = s.match(/^(-?)(\d+)\/(-?)(\d+)$/);
    if (m) {
      const sign = (m[1] ? -1 : 1) * (m[3] ? -1 : 1);
      const n = sign * parseInt(m[2], 10), d = parseInt(m[4], 10);
      if (!d) return null;
      return { kind: 'frac', n: n, d: d, value: n / d };
    }
    if (/^-?\d+$/.test(s)) return { kind: 'int', value: parseInt(s, 10) };
    if (/^-?\d*,\d+$/.test(s)) return { kind: 'dec', value: parseFloat(s.replace(',', '.')) };
    return null;
  };
  const near = (a, b) => Math.abs(a - b) <= 1e-9 * Math.max(1, Math.abs(a), Math.abs(b));
  U.checkNum = (input, ans) => {
    const p = U.parseNum(input);
    if (!p) return false;
    if (ans.kind === 'frac') {
      const n = ans.v[0], d = ans.v[1];
      if (p.kind === 'frac') {
        if (!near(p.value, n / d)) return false;
        if (ans.simplest) { const r = U.reduce(p.n, p.d); return r[0] === p.n * (p.d < 0 ? -1 : 1) && Math.abs(p.d) === r[1]; }
        return true;
      }
      if (d === 1) return p.kind !== 'dec' && near(p.value, n);
      return !ans.simplest && near(p.value, n / d);
    }
    if (p.kind === 'frac') return false;
    return near(p.value, ans.v);
  };
  // canonical input string for an answer (used by tests and to display)
  U.ansInput = ans => {
    if (ans.kind === 'frac') return ans.v[1] === 1 ? String(ans.v[0]) : ans.v[0] + '/' + ans.v[1];
    return U.trimDec(ans.v).replace('.', ',');
  };
  U.ansHtml = (ans, unit) => {
    let s = ans.kind === 'frac' ? U.F(ans.v[0], ans.v[1]) : U.fmt(ans.v);
    return s + (unit ? ' ' + unit : '');
  };
  U.normText = s => String(s == null ? '' : s).toLowerCase().replace(/[’‘`´]/g, "'").replace(/\s+/g, ' ').trim().replace(/[.!?]+$/, '').trim();
  U.checkText = (input, answers) => { const x = U.normText(input); return answers.some(a => U.normText(a) === x); };
  U.check = (q, resp) => {
    if (resp == null) return false;
    switch (q.t) {
      case 'mc': return resp === q.a;
      case 'num': return U.checkNum(resp, q.a);
      case 'text': return U.checkText(resp, q.a);
      case 'spell': return String(resp) === q.a;
      case 'order': {
        const r = Array.isArray(resp) ? resp.join(' ') : String(resp);
        return [q.a].concat(q.alts || []).some(x => x === r);
      }
    }
    return false;
  };
  U.correctHtml = q => {
    switch (q.t) {
      case 'mc': return q.opts[q.a];
      case 'num': return U.ansHtml(q.a, q.unit);
      case 'text': return U.esc(q.a[0]);
      case 'spell': return U.esc(q.a);
      case 'order': return U.esc(q.a);
    }
    return '';
  };

  // ---------- Toán song ngữ Anh – Việt ----------
  // Mỗi câu Toán có thêm qEn (đề tiếng Anh, cùng cấu trúc HTML với q). Lựa chọn trắc nghiệm có chữ tiếng Việt
  // được dịch qua bảng HV.EN_OPT (đăng ký bằng HV.enOpt). Thuật ngữ tiếng Anh của từng dạng: HV.mathTerms;
  // công thức / quy tắc bằng tiếng Anh: HV.ruleEn (hiện trong Cẩm nang).
  HV.EN_OPT = HV.EN_OPT || {};
  HV.enOpt = map => Object.assign(HV.EN_OPT, map);
  HV.TERMS = HV.TERMS || {};
  HV.mathTerms = (key, list) => { HV.TERMS[key] = (HV.TERMS[key] || []).concat(list); };
  HV.RULE_EN = HV.RULE_EN || {};
  HV.ruleEn = (key, html) => { HV.RULE_EN[key] = html; };
  U.moneyEn = n => U.fmt(n) + ' dong';

  // ---------- dates ----------
  U.pad = n => (n < 10 ? '0' : '') + n;
  U.dayKey = d => { d = d || new Date(); return d.getFullYear() + '-' + U.pad(d.getMonth() + 1) + '-' + U.pad(d.getDate()); };
  U.addDays = (key, k) => { const p = key.split('-').map(Number); const d = new Date(p[0], p[1] - 1, p[2] + k); return U.dayKey(d); };
  U.weekStart = key => { // Monday of the week containing key
    const p = key.split('-').map(Number); const d = new Date(p[0], p[1] - 1, p[2]);
    const dow = (d.getDay() + 6) % 7; d.setDate(d.getDate() - dow); return U.dayKey(d);
  };
  U.dowVi = key => { const p = key.split('-').map(Number); const d = new Date(p[0], p[1] - 1, p[2]).getDay(); return ['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'][d]; };
})(globalThis.HV = globalThis.HV || {});

