    const it = t === 2 ? pick([['con gà', 'chân', 'Mỗi con gà có 2 chân', 'A chicken has 2 legs. How many legs do ', ' chickens have?'], ['bạn', 'quyển vở', 'Mỗi bạn được thưởng 2 quyển vở', 'Each child gets 2 notebooks as a prize. How many notebooks do ', ' children get?'], ['đôi đũa', 'chiếc đũa', 'Mỗi đôi đũa có 2 chiếc', 'A pair of chopsticks has 2 chopsticks. How many chopsticks are there in ', ' pairs?']]) : pick([['bàn tay', 'ngón tay', 'Mỗi bàn tay có 5 ngón tay', 'A hand has 5 fingers. How many fingers are there on ', ' hands?'], ['đĩa', 'quả cam', 'Mỗi đĩa có 5 quả cam', 'Each plate has 5 oranges. How many oranges are there on ', ' plates?'], ['bó hoa', 'bông hoa', 'Mỗi bó có 5 bông hoa', 'Each bunch has 5 flowers. How many flowers are there in ', ' bunches?']]);
