    return Object.assign(mcNum(it[1], it[2], { min: 0, int: true }), { q: it[0], qEn: it[3], ex: steps(['Đáp án: ' + ans(it[1]) + '.', it[1] === 987 ? 'Chọn chữ số lớn nhất cho hàng trăm (9), rồi hàng chục (8), hàng đơn vị (7).' : it[1] === 102 ? 'Hàng trăm nhỏ nhất là 1, hàng chục là 0, hàng đơn vị nhỏ nhất khác 1 và 0 là 2.' : '']) });
