    if (lv === 2) return num(q, { q: it[0] + '. Hỏi phần đã ' + (it[1] === 'kg' ? 'bán' : it[1] === 'l' ? 'dùng' : 'cắt') + ' là bao nhiêu ' + (it[1] === 'kg' ? 'ki-lô-gam' : it[1] === 'l' ? 'lít' : 'mét') + '?', qEn: it[2] + '. ' + it[3], unit: it[1], ex: steps([n + ' : ' + k + ' = ' + ans(q + ' ' + it[1]) + '.']) });
    return num(n - q, { q: it[0] + '. Hỏi còn lại bao nhiêu ' + (it[1] === 'kg' ? 'ki-lô-gam' : it[1] === 'l' ? 'lít' : 'mét') + '?', qEn: it[2] + '. ' + it[4], unit: it[1], ex: steps(['Phần đã ' + (it[1] === 'kg' ? 'bán' : it[1] === 'l' ? 'dùng' : 'cắt') + ': ' + n + ' : ' + k + ' = ' + q + ' (' + it[1] + ').', 'Còn lại: ' + n + ' − ' + q + ' = ' + ans((n - q) + ' ' + it[1]) + '.']) });
