    if (t === 1) { const a = int(1, 9), b = int(1, 9); return num(a * 100 + b, { q: 'Số?<br><span class="big">' + a + ' m ' + b + ' cm = ' + box() + ' cm</span>', qEn: 'Fill in the missing number.<br><span class="big">' + a + ' m ' + b + ' cm = ' + box() + ' cm</span>', unit: 'cm', ex: steps([a + ' m = ' + a * 100 + ' cm.', a * 100 + ' + ' + b + ' = ' + ans(a * 100 + b) + ' cm.']) }); }
