    if (t === 1) { const A = coprimeFrac(9, true), B = coprimeFrac(9, true); const r = FR.div(A, B); return fracNum(r, { q: 'Tính (phân số tối giản):<br><span class="big">' + fA(A) + ' : ' + fA(B) + ' = ' + box() + '</span>', qEn: 'Work out (simplest form):<br><span class="big">' + fA(A) + ' : ' + fA(B) + ' = ' + box() + '</span>', ex: steps(['Chia cho một phân số là nhân với phân số đảo ngược: ' + fA(A) + ' × ' + F(B[1], B[0]) + ' = ' + F(A[0] * B[1], A[1] * B[0]) + '.', 'Rút gọn: ' + ans(fA(r)) + '.']) }); }
