      return fracNum(r, { q: 'Tính (phân số tối giản):<br><span class="big">' + F(A[0], A[1]) + (plus ? ' + ' : ' − ') + FP(B[0], B[1]) + ' = ' + box() + '</span>', qEn: 'Work out (simplest form):<br><span class="big">' + F(A[0], A[1]) + (plus ? ' + ' : ' − ') + FP(B[0], B[1]) + ' = ' + box() + '</span>', ex: steps(['Quy đồng mẫu số (mẫu chung ' + L + '): ' + F(A[0] * L / A[1], L) + (plus ? ' + ' : ' − ') + FP(B[0] * L / B[1], L) + '.', '= ' + F(plus ? A[0] * L / A[1] + B[0] * L / B[1] : A[0] * L / A[1] - B[0] * L / B[1], L) + ' = ' + ans(fA(r)) + '.']) });
