  for (let a = 1; a <= 15; a++) [a, a * a].forEach(n => { EN[X + ' = ' + n + ' hoặc ' + X + ' = −' + n] = X + ' = ' + n + ' or ' + X + ' = −' + n; }); // g7.real
  for (let s = -4; s <= 4; s++) for (let l = -4; l <= 4; l++) if (s && l) [[pairStr(s, s * s), pairStr(l, l * l)], [pairStr(-s, s * s), pairStr(-l, l * l)], [pairStr(s, l), pairStr(l, s)], [pairStr(s * s, s), pairStr(l * l, l)]].forEach(p => { EN[p[0] + ' và ' + p[1]] = p[0] + ' and ' + p[1]; }); // g9.parab
