      if (t === 1) { const d = int(1, 12), v2 = d / 10; return num(v2, { q: 'Tính:<br><span class="big">' + rt(fmt(v2 * v2)) + ' = ' + box() + '</span>', qEn: 'Work out:<br><span class="big">' + rt(fmt(v2 * v2)) + ' = ' + box() + '</span>', ex: steps(['Vì ' + fmt(v2) + SUP(2) + ' = ' + fmt(v2 * v2) + ' nên ' + rt(fmt(v2 * v2)) + ' = ' + ans(fmt(v2)) + '.']) }); }
