        return num(lead, { q: 'Hệ số cao nhất của đa thức ' + MH.terms(shown) + ' là:', qEn: 'The leading coefficient of the polynomial ' + MH.terms(shown) + ' is:', ex: steps(['Hệ số cao nhất là hệ số của hạng tử có bậc cao nhất (' + X + SUP(deg) + ').', 'Hệ số đó là ' + ans(fmt(lead)) + '.']) });
