  MH.picChart = (rows, cap, unit) => '<div class="pchart" role="img" aria-label="' + esc(cap + ': ' + rows.map(r => r[1] + ' ' + r[2]).join(', ')) + '"><div class="pc-cap">' + esc(cap) + '</div>' + rows.map(r => '<div class="pc-row"><span class="pc-lab">' + esc(r[1]) + '</span><span class="pc-ic">' + Array(r[2]).fill('<i>' + r[0] + '</i>').join('') + '</span></div>').join('') + '<div class="pc-note">Mỗi hình ứng với 1 ' + esc(unit) + '</div></div>';
  // vạch kiểm đếm: nhóm 4 vạch đứng + 1 vạch chéo
  MH.tally = n => { const g = Math.floor(n / 5), r = n % 5, W = g * 32 + r * 7 + 4; let s = '<svg class="tally" viewBox="0 0 ' + W + ' 30" width="' + W + '" height="30" aria-label="' + n + ' vạch">'; for (let i = 0; i < g; i++) { const x0 = 4 + i * 32; for (let j = 0; j < 4; j++) s += '<line x1="' + (x0 + j * 6) + '" y1="4" x2="' + (x0 + j * 6) + '" y2="26"/>'; s += '<line x1="' + (x0 - 3) + '" y1="22" x2="' + (x0 + 21) + '" y2="8"/>'; } for (let j = 0; j < r; j++) { const x = 4 + g * 32 + j * 7; s += '<line x1="' + x + '" y1="4" x2="' + x + '" y2="26"/>'; } return s + '</svg>'; };

