  const circleFig = (r, d) => svg(200, 140, 'Hình tròn tâm O', '<circle class="fig-shape" cx="100" cy="70" r="56"/>' + (d ? seg(44, 70, 156, 70) + dot(44, 70) + dot(156, 70) + lab(36, 66, 'A', 'end') + lab(164, 66, 'B', 'start') : seg(100, 70, 156, 70) + dot(156, 70) + lab(164, 66, 'A', 'start')) + dot(100, 70) + lab(100, 88, 'O') + (r ? lab(128, 62, r) : '') + (d ? lab(100, 62, d) : ''));

  // ======================= TIẾNG ANH (Toán song ngữ, dùng chung) =======================
  // Từ dùng trong đề tiếng Anh (qEn) và bản dịch các lựa chọn trắc nghiệm có chữ tiếng Việt (HV.EN_OPT).
  const COL_EN = { 'đỏ': 'red', 'xanh': 'blue', 'vàng': 'yellow' }, FACE_EN = { 'sấp': 'tails', 'ngửa': 'heads' }, PART_EN = { 'mặt': 'faces', 'cạnh': 'edges', 'đỉnh': 'vertices' };
  const art = s => (/^[aeiou]/i.test(s) ? 'an ' : 'a ');
