  const PL = { 'Táo': 'apples', 'Cam': 'oranges', 'Chuối': 'bananas', 'Dưa hấu': 'watermelons', 'Nho': 'grapes', 'Ô tô': 'cars', 'Xe máy': 'motorbikes', 'Xe đạp': 'bicycles', 'Xe buýt': 'buses', 'Gà': 'chickens', 'Vịt': 'ducks', 'Lợn': 'pigs', 'Bò': 'cows' };
