    return Object.assign(mcNum(it[1], [0, 1, 2, 3, 4], { min: 0, max: 4, int: true }), { q: '<b>' + it[0] + '</b> có mấy góc vuông?', qEn: 'How many right angles does this <b>' + SHP[it[0]] + '</b> have?', vis: svg(200, 110, it[0], it[2]), hint: 'Dùng ê ke để kiểm tra từng góc.', ex: steps([it[1] === 4 ? it[0] + ' có 4 góc đều là góc vuông.' : it[1] === 1 ? 'Tam giác vuông có đúng 1 góc vuông.' : 'Dùng ê ke kiểm tra: cả ba góc của hình tam giác này đều không vuông.', 'Đáp án: ' + ans(it[1]) + '.']) });
