      if (t === 'pa') { const a = int(6, 25), b = int(3, a - 1); return num(2 * (a + b), { q: 'Hình bình hành ABCD có AB = ' + a + ' cm, BC = ' + b + ' cm. Tính chu vi hình bình hành.', qEn: 'Parallelogram ABCD has AB = ' + a + ' cm and BC = ' + b + ' cm. Find the perimeter of the parallelogram.', unit: 'cm', vis: paraFig(false, a + ' cm', b + ' cm'), hint: 'Hình bình hành có các cạnh đối diện bằng nhau.', ex: steps(['Hình bình hành có AB = CD, BC = AD.', 'Chu vi = (' + a + ' + ' + b + ') × 2 = ' + ans(2 * (a + b) + ' cm') + '.']) }); }
