    if (chance(0.5)) { const [i, j] = sample(U.range(0, k - 1), 2), hi = P.pcts[i] > P.pcts[j] ? i : j, lo = hi === i ? j : i, v = N * (P.pcts[hi] - P.pcts[lo]) / 100; return num(v, { q: 'Có ' + N + ' ' + c.who + '. Theo biểu đồ, số ' + c.who + ' ' + actOf(c, P.names[hi]) + ' nhiều hơn số ' + c.who + ' ' + actOf(c, P.names[lo]) + ' là bao nhiêu?', qEn: 'There are ' + N + ' ' + c.en.who + '. Look at the pie chart. How many more ' + c.en.who + ' ' + c.en.act[P.names[hi]] + ' than ' + c.en.act[P.names[lo]] + '?', vis: P.vis, hint: 'Tỉ lệ chênh lệch: ' + P.pcts[hi] + '% − ' + P.pcts[lo] + '%.', ex: steps(['Chênh lệch: ' + P.pcts[hi] + '% − ' + P.pcts[lo] + '% = ' + (P.pcts[hi] - P.pcts[lo]) + '%.', N + ' × ' + (P.pcts[hi] - P.pcts[lo]) + ' : 100 = ' + ans(fmt(v)) + '.']) }); }
