      const q = pick(QUAL); return Object.assign(mcStr(q, sample(QUANT, 3)), { q: 'Dữ liệu nào sau đây là <b>dữ liệu định tính</b> (không phải là số)?', qEn: 'Which of these is <b>qualitative data</b> (not numbers)?', hint: 'Dữ liệu định tính là tên gọi, màu sắc, tính chất…', ex: steps(['Dữ liệu định tính không phải là số đo hay số đếm.', 'Đáp án: ' + ans(q) + '.']) });
