  const seqRow = (y, vals, o) => {
    o = o || {};
    const n = vals.length, w = o.w || 74, gap = o.gap || 24, x0 = 320 - (n * w + (n - 1) * gap) / 2;
    let s = '';
    vals.forEach((v, i) => {
      const x = x0 + i * (w + gap), q = v === '?';
      const box = rect(x, y, w, 66, q ? C.starS : C.white, { r: 14, st: q ? C.star : C.navy, sw: 3 }) + tx(x + w / 2, y + 45, v, { s: 34, w: 800, c: q ? '#A64B00' : C.ink });
      s += o.anim != null ? pop(o.anim + i * 0.25, box) : box;
      if (o.steps && i < n - 1 && o.steps[i]) s += pop((o.stepAnim || 0) + i * 0.6, '<path d="M' + (x + w / 2 + 6) + ' ' + (y - 6) + ' Q' + (x + w + gap / 2) + ' ' + (y - 46) + ' ' + (x + w + gap + w / 2 - 6) + ' ' + (y - 6) + '" style="fill:none;stroke:' + C.star + ';stroke-width:3"/>' + tx(x + w + gap / 2, y - 48, o.steps[i], { s: 22, w: 800, c: '#A64B00', f: FB }));
    });
    return s;
  };
