  // Bộ công cụ vẽ cảnh dùng chung cho bài giảng tự động (42-lesson-auto.js)
  HV.LESSON_KIT = { C: C, FD: FD, FB: FB, tx: tx, an: an, at: at, emo: emo, rect: rect, circ: circ, ln: ln, pop: pop, fade: fade, up: up, sparkle: sparkle, tick: tick, V: V, E: E, P: P };
  // Bài giảng làm tay; 42-lesson-auto.js ghép thêm bài tự động cho mọi dạng bài và dựng danh mục theo lớp
  HV.LESSONS_HAND = [L_ADD, L_CLOCK, L_AREA, L_FRAC, L_EQ, L_CHICK, L_TREES, L_SEQ, L_TH, L_PLURAL, L_PRES, L_HELLO];
  HV.LESSONS_HAND.forEach(l => { l.secs = Math.round(l.scenes.reduce((s, sc) => s + sc.ms + 700, 0) / 1000); });
