    const T = HV.TOPICS[s.k];
    const L = { id: 'a.' + s.k + (s.subj === 'math' ? '' : '.' + s.vk), subj: s.subj, topic: s.k, vk: s.vk, auto: true, title: T.name, icon: iconFor(s.k), secs: 85,
      sub: s.subj === 'math' ? gradeLabel(T.g) + ' · Toán' : s.subj === 'eng' ? 'Tiếng Anh · Cấp ' + s.vk : 'Tư duy · ' + gradeLabel(s.vk) };
    let sc = null;
    Object.defineProperty(L, 'scenes', { enumerable: true, get: () => { if (!sc) { sc = build(L); L.secs = Math.round(sc.reduce((a, x) => a + x.ms + 700, 0) / 1000); } return sc; } });
