  HV.LESSON = BY;
  HV.lessonId = (k, vk) => SLOT[k + '|' + vk] || null;
  // bài giảng phù hợp với một bé cho một dạng bài (theo lớp / cấp / nhóm của bé)
  HV.lessonForKid = (k, kid) => { const T = HV.TOPICS[k]; return T ? HV.lessonId(k, HV.keyForTopic(T, kid)) : null; };
