  const PH_NAME = { open: '1. Mở bài — quay', teach: '2. Giảng bài trên bảng — quay', think: '3. Đến lượt con — ứng dụng tự hỏi sau video', fix: '4. Chữa bài và ghi nhớ — ứng dụng tự chữa sau video' };
