    s = s.replace(/≠/g, ' khác ').replace(/≤/g, ' bé hơn hoặc bằng ').replace(/≥/g, ' lớn hơn hoặc bằng ').replace(/</g, ' bé hơn ').replace(/>/g, ' lớn hơn ').replace(/=/g, ' bằng ');
    s = s.replace(/\s*∽\s*/g, ' đồng dạng với ').replace(/⇔/g, ', tương đương, ').replace(/⇒|→|➜/g, ', ').replace(/∈/g, ' thuộc ').replace(/∉/g, ' không thuộc ').replace(/∠/g, ' góc ').replace(/△|Δ(?=\s*[A-Z])/g, ' tam giác ');
