    const pre = pk[0][10] + pk[0][11] * 256, total = au.length * 960; // pre-skip của bộ mã hoá; mỗi gói 20 ms = 960 mẫu
    const end = gran > pre && gran <= total ? gran : total;
    const table = [];
    au.forEach(b => { let n = b.length; const t = [n & 127]; n >>>= 7; while (n) { t.unshift((n & 127) | 128); n >>>= 7; } t.forEach(x => table.push(x)); });
    const dataLen = au.reduce((x, b) => x + b.length, 0);
