    if (cfg.mode === 'review') { ses.queue = U.shuffle(k.mistakes.map(m => m.id)).slice(0, Math.min(10, k.mistakes.length)); ses.len = ses.queue.length; if (!ses.len) return; }
    if (cfg.mode === 'topic') ses.fixedLv = (UI.S.lvPick || {})[cfg.topics[0]] || 0;
    ses.subj = cfg.subj || (HV.TOPICS[ses.topics[0]] && HV.TOPICS[ses.topics[0]].subj) || 'math';
    UI.S.ses = ses;
