  // ---------- xuất / nhập dữ liệu ----------
  A.expJson = () => {
    const data = { app: 'hoc-vien-ngoi-sao', v: 1, exported: new Date().toISOString(), meta: Object.assign({}, ST.state.meta, { pin: '', prem: undefined }), kids: ST.state.kids };
    UI.DL.save('hvns-sao-luu-' + U.dayKey() + '.json', JSON.stringify(data, null, 1));
  };
  const csvCell = v => { let s = String(v == null ? '' : v); if (/^[=+\-@]/.test(s)) s = "'" + s; return /[",;\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const csv = rows => '﻿' + rows.map(r => r.map(csvCell).join(',')).join('\r\n');
  A.expCsv = d => {
    const kids = ST.kidList();
    let rows, name;
    if (d.v === 'topics') {
      rows = [['Hồ sơ', 'Môn', 'Dạng bài', 'Lớp/Cấp', 'Số câu đã làm', 'Số câu đúng', 'Tỉ lệ đúng 20 câu gần nhất (%)', 'Mức hiện tại', 'Trạng thái', 'Lần luyện gần nhất']];
      kids.forEach(k => topicRows(k).forEach(x => rows.push([k.name, ST.SUBJ[x.T.subj].name, x.T.name, HV.topicPlace(x.T), x.ts.n, x.ts.c, x.m.acc == null ? '' : Math.round(x.m.acc * 100), LVN[x.ts.lv || 1], STATUS_TXT[x.m.status] || '', x.ts.t ? U.dayKey(new Date(x.ts.t)) : ''])));
      name = 'hvns-dang-bai-' + U.dayKey() + '.csv';
    } else {
      rows = [['Hồ sơ', 'Ngày', 'Tổng câu', 'Câu đúng', 'Tỉ lệ đúng (%)', 'Thời gian (phút)', 'Toán - câu', 'Toán - đúng', 'Tiếng Anh - câu', 'Tiếng Anh - đúng', 'Tư duy - câu', 'Tư duy - đúng', 'Sao kiếm được', 'Đạt mục tiêu ngày']];
      kids.forEach(k => Object.keys(k.days).sort().forEach(key => {
        const x = k.days[key], s = x.s || {}, g = t => s[t] || [0, 0];
        rows.push([k.name, key, x.n, x.c, x.n ? Math.round(x.c / x.n * 100) : '', Math.round(x.ms / 60000), g('math')[0], g('math')[1], g('eng')[0], g('eng')[1], g('logic')[0], g('logic')[1], x.st || 0, x.g ? 'Có' : 'Chưa']);
      }));
      name = 'hvns-nhat-ky-' + U.dayKey() + '.csv';
    }
    if (rows.length < 2) { UI.toast('Chưa có dữ liệu để xuất'); return; }
    UI.DL.save(name, csv(rows));
  };
  const isNum = v => typeof v === 'number' && isFinite(v);
  const nInt = (v, lo, hi, d) => (isNum(v) ? Math.max(lo, Math.min(hi, Math.round(v))) : d);
