      const vw = {}, VMAP = HV.VOC ? HV.VOC.map() : {};
      Object.keys(o.voc.w).slice(0, 5000).forEach(id => { const r = o.voc.w[id]; if (VMAP[id] && Array.isArray(r)) vw[id] = [nInt(r[0], 1, 5, 1), nInt(r[1], 0, 1e6, 0), nInt(r[2], 0, 1e5, 1), nInt(r[3], 0, 1e5, 0), nInt(r[4], 0, 1e6, 0)]; });
