  // ---------- giọng đọc: chọn giọng tiếng Việt / tiếng Anh của máy, tốc độ, nghe thử (lưu riêng trên từng máy) ----------
  const RATES = { Vi: [[0.85, 'Chậm'], [1, 'Vừa'], [1.12, 'Nhanh']], En: [[0.75, 'Chậm'], [0.88, 'Vừa'], [1, 'Nhanh']] };
  A.voiceEdit = () => { const T = UI.TTS; if (T.load) T.load(); UI.S.vsave = JSON.stringify(T.pref || {}); UI.openModal('voiceForm'); };
