  A.vfRate = d => { vfRead(); UI.TTS.pref['rate' + d.k] = +d.v; UI.render(); };
  A.vfTestVi = () => { vfRead(); UI.TTS.say('Chào con! Hôm nay ' + UI.gv().pron + ' cùng con học bảng nhân 7: 7 × 8 = 56. Con giỏi lắm!', 'vi-VN'); };
  A.vfTestClip = () => { vfRead(); UI.TTS.speak('Good morning.'); };
