  A.vfSave = () => { vfRead(); UI.TTS.savePref(); UI.S.vsave = null; UI.S.modal = null; UI.toast('Đã lưu giọng đọc cho máy này'); UI.render(); };
  A.vfCancel = () => { try { UI.TTS.pref = JSON.parse(UI.S.vsave || '{}'); } catch (e) { UI.TTS.pref = {}; } UI.TTS.stop(); UI.S.modal = null; UI.render(); };
  M.voiceForm = () => {
    const T = UI.TTS, P = T.pref || {};
    const sel = (id, list, cur) => list.length ? '<select id="' + id + '" class="input">' + list.map((v, i) => { const val = v.voiceURI || v.name; return '<option value="' + esc(val) + '"' + ((cur ? val === cur || v.name === cur : i === 0) ? ' selected' : '') + '>' + esc(v.name + (v.lang ? ' · ' + v.lang : '')) + (i === 0 ? ' — khuyên dùng' : '') + '</option>'; }).join('') + '</select>' : '';
    const rate = k => '<div class="seg">' + RATES[k].map(r => '<button class="' + (Math.abs(T.rate(k) - r[0]) < 0.01 ? 'on' : '') + '" data-a="vfRate" data-k="' + k + '" data-v="' + r[0] + '">' + r[1] + '</button>').join('') + '</div>';
    const vis = T.list ? T.list('vi-VN') : [], ens = T.list ? T.list('en-US') : [];
    const nClip = T.clip && T.clip.idx ? Object.keys(T.clip.idx).length : 0;
    return UI.modalWrap('<h2>Giọng đọc</h2>' +
      '<div class="field"><span class="lbl">Tiếng Anh — giọng chuẩn thu sẵn</span><div class="row"><span class="grow muted" style="font-size:.9rem">' + (nClip ? 'Đã có ' + U.fmt(nClip) + ' từ và câu đọc sẵn bằng giọng nữ Mỹ rõ, ấm: từ vựng, mẫu câu, hội thoại, bài đọc, lời tiếng Anh trong bài giảng. Đọc giống nhau trên mọi máy.' : 'Bản này chưa kèm giọng thu sẵn — dùng giọng của máy.') + '</span>' + (nClip ? '<button class="btn sm ghost" data-a="vfTestClip">' + I('play') + 'Nghe thử</button>' : '') + '</div></div>' +
      '<div class="field"><span class="lbl">Tiếng Việt — giọng của máy</span>' + (vis.length ? sel('vf-vi', vis, P.vi) : '<div class="hint">' + I('triangle-alert') + '<span>Máy này chưa có giọng tiếng Việt. Bài giảng sẽ hiện chữ thay cho lời đọc — xem cách cài giọng ở dưới.</span></div>') +
      '<div class="row wrapr" style="gap:8px;margin-top:8px">' + rate('Vi') + (vis.length ? '<button class="btn sm ghost" data-a="vfTestVi">' + I('play') + 'Nghe thử</button>' : '') + '</div></div>' +
      '<div class="field"><span class="lbl">Tiếng Anh — câu tự sinh (dùng giọng của máy)</span>' + (ens.length ? sel('vf-en', ens, P.en) : '<small class="muted">Máy chưa có giọng tiếng Anh.</small>') +
      '<div class="row wrapr" style="gap:8px;margin-top:8px">' + rate('En') + (ens.length ? '<button class="btn sm ghost" data-a="vfTestEn">' + I('play') + 'Nghe thử</button>' : '') + '</div></div>' +
      '<details class="voice-help"><summary><b>Muốn giọng tiếng Việt hay, ấm hơn?</b></summary><ul>' +
      '<li><b>iPhone / iPad:</b> Cài đặt → Trợ năng → Nội dung được đọc → Giọng nói → Tiếng Việt → tải giọng <b>Linh (Nâng cao)</b>. Mở lại ứng dụng rồi chọn giọng đó ở trên.</li>' +
      '<li><b>Android:</b> Cài đặt → tìm “Chuyển văn bản thành giọng nói” → chọn <b>Dịch vụ của Google</b> → tải dữ liệu giọng <b>Tiếng Việt</b>.</li>' +
      '<li><b>Máy tính Windows:</b> mở bằng trình duyệt <b>Edge</b> để có giọng <b>HoaiMy (Natural)</b> rất tự nhiên.</li></ul>' +
      '<small class="muted">Ứng dụng tự đổi số, phép tính, đơn vị sang chữ trước khi đọc (vd 7 × 8 = 56 → “bảy nhân tám bằng năm mươi sáu”) và để giọng tiếng Anh đọc các từ tiếng Anh, nên không còn đọc sai hay bỏ sót ký hiệu.</small></details>' +
      '<div class="row"><button class="btn primary grow" data-a="vfSave">' + I('check') + 'Lưu cho máy này</button><button class="btn ghost" data-a="vfCancel">Hủy</button></div>', 'Giọng đọc');
  };
