  A.lesSubj = d => { UI.S.lesS = d.v; UI.render(); };
  const lessonCard = (k, L) => {
    const T = HV.TOPICS[L.topic], seen = (k.lessons || {})[L.id], prem = !!(UI.premLocked && UI.premLocked.lesson(L));
    return '<button class="les-card' + (prem ? ' prem' : '') + '" data-a="openLesson" data-id="' + L.id + '"><span class="les-thumb ' + L.subj + '">' + L.icon + '</span><span class="grow"><b>' + esc(L.title) + '</b><small>' + esc(T && T.desc ? T.desc : L.sub) + ' · khoảng ' + mins(L) + ' phút</small>' +
      '<span class="row" style="gap:6px;margin-top:4px">' + (prem ? UI.premTag() : seen ? '<span class="tag ok">' + I('circle-check') + 'Đã xem</span>' : '<span class="tag star">' + I('star') + '+' + reward(L) + ' sao</span>') + (L.auto ? '' : '<span class="tag">🎬 Phim hoạt hình</span>') + (UI.Vid && UI.Vid.has(L.id) ? '<span class="tag vid">' + I('tv') + 'Video thầy cô</span>' : '') + '</span></span>' + I(prem ? 'lock' : 'play') + '</button>';
  };
